# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">THEME 3: HUMAN RIGHTS COLLOCATIONS &amp; UNIVERSAL DECLARATION</text>\n\n  <!-- Sol Kutu: Collocations -->\n  <rect x="18" y="45" width="320" height="198" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="178" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">KEY COLLOCATIONS (EŞDİZİMLİLİKLER)</text>\n  <line x1="32" y1="76" x2="324" y2="76" stroke="#93c5fd" stroke-width="1.5"/>\n  <text x="32" y="96" font-size="10.5" fill="#1e3a8a">• gender equality: cinsiyet eşitliği</text>\n  <text x="32" y="114" font-size="10.5" fill="#1e3a8a">• freedom of thought: düşünce özgürlüğü</text>\n  <text x="32" y="132" font-size="10.5" fill="#1e3a8a">• the right to seek help: yardım arama hakkı</text>\n  <text x="32" y="150" font-size="10.5" fill="#1e3a8a">• workers\' rights: işçi hakları</text>\n  <text x="32" y="168" font-size="10.5" fill="#1e3a8a">• disadvantaged groups: dezavantajlı gruplar</text>\n  <text x="32" y="186" font-size="10.5" fill="#1e3a8a">• launch a campaign: kampanya başlatmak</text>\n  <text x="32" y="204" font-size="10.5" fill="#1e3a8a">• respect to others: başkalarına saygı</text>\n  <text x="32" y="222" font-size="10.5" font-weight="bold" fill="#be123c">• human rights abuses: insan hakları ihlalleri</text>\n\n  <!-- Sağ Kutu: Universal Declaration of Human Rights -->\n  <rect x="354" y="45" width="328" height="198" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">UNIVERSAL DECLARATION OF HUMAN RIGHTS</text>\n  <line x1="368" y1="76" x2="668" y2="76" stroke="#86efac" stroke-width="1.5"/>\n  <text x="370" y="98" font-size="10.5" font-weight="bold" fill="#14532d">• "We are all born free and equal."</text>\n  <text x="370" y="118" font-size="10.5" fill="#166534">• "Everyone is entitled to these rights."</text>\n  <text x="370" y="138" font-size="10.5" fill="#166534">• "Right to life, freedom, and safety."</text>\n  <text x="370" y="158" font-size="10.5" font-weight="bold" fill="#14532d">• "Everyone is innocent until proven guilty."</text>\n  <text x="370" y="178" font-size="10.5" fill="#166534">• "Right to a fair and public trial &amp; privacy."</text>\n  <text x="370" y="198" font-size="10.5" fill="#166534">• "Right to education &amp; adequate living standard."</text>\n  <rect x="370" y="208" width="296" height="24" rx="5" fill="#dcfce7"/>\n  <text x="518" y="224" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">İnsan Hakları Evrensel Bildirgesi Temel İlkeleri</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">DISADVANTAGED GROUPS &amp; MAKING SUGGESTIONS (ÖNERİ KALIPLARI)</text>\n\n  <!-- Sol Kutu: Sorunlar ve Çözümler -->\n  <rect x="18" y="45" width="295" height="198" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="165" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#a16207">PROBLEMS &amp; SOLUTIONS</text>\n  <line x1="30" y1="76" x2="300" y2="76" stroke="#fde047" stroke-width="1.5"/>\n  <text x="30" y="96" font-size="10" font-weight="bold" fill="#b91c1c">Problems of Disadvantaged Groups:</text>\n  <text x="36" y="112" font-size="9.5" fill="#713f12">• Being deprived of education or books</text>\n  <text x="36" y="128" font-size="9.5" fill="#713f12">• Drawing water from wells &amp; carrying buckets</text>\n  <text x="30" y="150" font-size="10" font-weight="bold" fill="#15803d">Solutions (Çözüm Yolları):</text>\n  <text x="36" y="166" font-size="9.5" fill="#713f12">• Arranging charity events (hayır etkinliği)</text>\n  <text x="36" y="182" font-size="9.5" fill="#713f12">• Raising people\'s awareness (farkındalık)</text>\n  <text x="36" y="198" font-size="9.5" fill="#713f12">• Applying to officials / Finding sponsors</text>\n  <text x="36" y="214" font-size="9.5" fill="#713f12">• Launching a book donation campaign</text>\n\n  <!-- Sağ Kutu: 5 Suggestion Kalıbı -->\n  <rect x="328" y="45" width="354" height="198" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="505" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">MAKING SUGGESTIONS (FİİL KURALI)</text>\n  <line x1="342" y1="76" x2="668" y2="76" stroke="#d8b4fe" stroke-width="1.5"/>\n  <text x="342" y="96" font-size="10.5" font-weight="bold" fill="#581c87">1) Why don\'t we + V1 ...?</text>\n  <text x="350" y="110" font-size="9.5" fill="#6b21a8">"Why don\'t we contact charity organizations?"</text>\n  <text x="342" y="130" font-size="10.5" font-weight="bold" fill="#be123c">2) I suggest + V-ing ...!</text>\n  <text x="350" y="144" font-size="9.5" fill="#9f1239">"I suggest helping dig more wells."</text>\n  <text x="342" y="164" font-size="10.5" font-weight="bold" fill="#581c87">3) Let\'s + V1 ...</text>\n  <text x="350" y="178" font-size="9.5" fill="#6b21a8">"Let\'s launch a book donation campaign."</text>\n  <text x="342" y="198" font-size="10.5" font-weight="bold" fill="#be123c">4) How about / What about + V-ing ...?</text>\n  <text x="350" y="212" font-size="9.5" fill="#9f1239">"How about raising money for them to buy new books?"</text>\n  <text x="342" y="232" font-size="10.5" font-weight="bold" fill="#581c87">5) We should / ought to + V1 ...</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">WRITING AN ARGUMENTATIVE ESSAY ON HUMAN RIGHTS</text>\n\n  <!-- 4 Paragraf Kutusu -->\n  <rect x="18" y="42" width="322" height="94" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="179" y="62" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">1. INTRODUCTION (GİRİŞ)</text>\n  <text x="30" y="80" font-size="10" fill="#1e3a8a">• Gives background information on the topic.</text>\n  <text x="30" y="96" font-size="10" font-weight="bold" fill="#1e40af">• States the Thesis Statement (Ana Tez):</text>\n  <text x="30" y="112" font-size="9.2" fill="#334155">"...one of the best ways to help them is to arrange</text>\n  <text x="30" y="125" font-size="9.2" fill="#334155">charity events, although some believe that it is not so."</text>\n\n  <rect x="358" y="42" width="324" height="94" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="62" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">2. FIRST &amp; SECOND BODY PARAGRAPHS</text>\n  <text x="370" y="80" font-size="10" fill="#14532d">• Topic Sentence + Supporting Details (Pros):</text>\n  <text x="370" y="96" font-size="9.5" fill="#166534">- Body 1: Bringing together a lot of people easily.</text>\n  <text x="370" y="112" font-size="9.5" fill="#166534">- Body 2: "In addition, charity events draw people\'s</text>\n  <text x="378" y="125" font-size="9.5" fill="#166534">attention to problems and raise awareness."</text>\n\n  <rect x="18" y="148" width="322" height="96" rx="8" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="179" y="168" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#be123c">3. THIRD BODY (COUNTERPOINT &amp; REBUTTAL)</text>\n  <text x="30" y="186" font-size="10" font-weight="bold" fill="#881337">• Counterpoint ("On the other hand..."):</text>\n  <text x="36" y="201" font-size="9.2" fill="#9f1239">"Some people argue that charity events require effort."</text>\n  <text x="30" y="218" font-size="10" font-weight="bold" fill="#15803d">• Rebutting (Karşı görüşü çürütme):</text>\n  <text x="36" y="232" font-size="9.2" fill="#1e293b">Refutes the opposing view with strong evidence.</text>\n\n  <rect x="358" y="148" width="324" height="96" rx="8" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="520" y="168" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#a16207">4. CONCLUSION (SONUÇ)</text>\n  <text x="370" y="188" font-size="10" font-weight="bold" fill="#713f12">• Starts with "In conclusion, ..."</text>\n  <text x="370" y="206" font-size="10" fill="#854d0e">• Summarizes the main arguments.</text>\n  <text x="370" y="224" font-size="10" font-weight="bold" fill="#713f12">• Restates the writer\'s opinion in different words.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
